1	// Package rollup downsamples a time series into fixed windows aligned to
2	// the Unix epoch, and merges rollups that share a window size.
3	//
4	// A Roller is safe for concurrent use: samples may be filed, windows read,
5	// and rollers merged from multiple goroutines at once. Every read observes
6	// an internally consistent snapshot, and a merge or batch is visible to
7	// other callers either in full or not at all.
8	package rollup
9	
10	import (
11		"errors"
12		"math"
13		"math/bits"
14		"sync"
15		"sync/atomic"
16		"time"
17	)
18	
19	// ErrOutOfOrder is returned by Add when a sample predates the most recent
20	// sample the roller has already accepted.
21	var ErrOutOfOrder = errors.New("rollup: out of order")
22	
23	// ErrWindowMismatch is returned by Merge when the two rollers use different
24	// window sizes.
25	var ErrWindowMismatch = errors.New("rollup: window mismatch")
26	
27	// Sample is one record in a batch passed to AddBatch: a value observed at
28	// one instant.
29	type Sample struct {
30		At    time.Time
31		Value float64
32	}
33	
34	// Window holds the aggregate statistics of the samples filed into one
35	// window. Start is the window's left-closed, right-open lower bound.
36	type Window struct {
37		Start time.Time
38		Count int64
39		Sum   float64
40		Min   float64
41		Max   float64
42	}
43	
44	// Roller aggregates samples into fixed windows of a single size.
45	//
46	// The zero value is not usable; build one with New. All methods are safe
47	// to call concurrently from multiple goroutines.
48	type Roller struct {
49		// mu guards buckets, back, latest, and hasAny. window and id are
50		// fixed at construction and read without the lock.
51		//
52		// buckets is one flat slice kept sorted by window start: samples
53		// arrive in non-decreasing time order, so Add appends in amortized
54		// constant time, Windows reads out without re-sorting, and Merge is
55		// a single linear pass over both sides.
56		//
57		// back is a second sorted slice holding backfilled windows: a sample
58		// that lands before the newest window opens its bucket here, so the
59		// insert never shifts the tail of buckets and mass backfills stay
60		// cheap. back is folded into buckets once it is large enough for
61		// the merge to amortize. Every read consults both slices, and no
62		// window start appears in both at the same time.
63		mu      sync.RWMutex
64		id      uint64
65		window  time.Duration
66		buckets []Window
67		back    []Window
68		latest  time.Time
69		hasAny  bool
70	}
71	
72	// idGen hands out unique roller IDs so Merge can lock two rollers in a
73	// consistent order and concurrent cross-merges cannot deadlock.
74	var idGen atomic.Uint64
75	
76	// New builds a roller with the given window size. It panics with
77	// "rollup: bad window" if window is not positive.
78	func New(window time.Duration) *Roller {
79		if window <= 0 {
80			panic("rollup: bad window")
81		}
82		return &Roller{
83			id:     idGen.Add(1),
84			window: window,
85		}
86	}
87	
88	// startOf returns the start of the window containing at, aligned to an
89	// integer multiple of the window size since the Unix epoch.
90	func (r *Roller) startOf(at time.Time) time.Time {
91		return alignStart(at, r.window.Nanoseconds())
92	}
93	
94	// alignStart returns the start of the window of width w nanoseconds
95	// containing at, aligned to an integer multiple of w since the Unix epoch.
96	// The arithmetic is exact for any time value, including ones whose
97	// nanosecond offset from the epoch does not fit in an int64.
98	func alignStart(at time.Time, w int64) time.Time {
99		sec := at.Unix()
100		nsec := int64(at.Nanosecond())
101		if sec >= -9223372036 && sec <= 9223372035 {
102			// sec*1e9+nsec fits in an int64. Rounding a negative ns down to
103			// a window multiple can reach ns-(w-1), so stay on the fast
104			// path only when that product cannot overflow either.
105			if ns := sec*1e9 + nsec; ns >= math.MinInt64+w-1 {
106				start := ns / w
107				if ns%w != 0 && ns < 0 {
108					start--
109				}
110				return time.Unix(0, start*w).UTC()
111			}
112		}
113		return windowStartWide(sec, nsec, w)
114	}
115	
116	// windowStartWide is the 128-bit slow path of alignStart, for times whose
117	// nanosecond offset from the epoch overflows an int64.
118	func windowStartWide(sec, nsec, w int64) time.Time {
119		// t = sec*1e9 + nsec as a 128-bit two's-complement value (hi, lo).
120		uhi, ulo := bits.Mul64(uint64(sec), uint64(1e9))
121		if sec < 0 {
122			uhi -= 1e9
123		}
124		hi := int64(uhi)
125		lo := ulo + uint64(nsec)
126		if lo < ulo {
127			hi++
128		}
129		// Round t down to a multiple of w: start = t - floorMod(t, w).
130		rem := floorMod128(hi, lo, w)
131		if lo < rem {
132			hi--
133		}
134		lo -= rem
135		// Split start into whole seconds and nanoseconds.
136		ns := floorMod128(hi, lo, 1e9)
137		if lo < ns {
138			hi--
139		}
140		lo -= ns
141		return time.Unix(quo128(hi, lo, 1e9), int64(ns)).UTC()
142	}
143	
144	// floorMod128 returns t mod y for the signed 128-bit value t = (hi<<64)|lo
145	// and positive y, with the result in [0, y).
146	func floorMod128(hi int64, lo uint64, y int64) uint64 {
147		yu := uint64(y)
148		if hi >= 0 {
149			return rem128(uint64(hi), lo, yu)
150		}
151		// Negate the 128-bit value, take the remainder, and reflect it back
152		// into [0, y) for floored (not truncated) division.
153		mlo := -lo
154		mhi := -uint64(hi)
155		if lo != 0 {
156			mhi--
157		}
158		if r := rem128(mhi, mlo, yu); r != 0 {
159			return yu - r
160		}
161		return 0
162	}
163	
164	// quo128 returns (hi<<64|lo)/y for a signed 128-bit dividend known to be an
165	// exact multiple of y, with a quotient that fits in an int64.
166	func quo128(hi int64, lo uint64, y int64) int64 {
167		yu := uint64(y)
168		if hi >= 0 {
169			q, _ := bits.Div64(uint64(hi), lo, yu)
170			return int64(q)
171		}
172		mlo := -lo
173		mhi := -uint64(hi)
174		if lo != 0 {
175			mhi--
176		}
177		q, _ := bits.Div64(mhi, mlo, yu)
178		return -int64(q)
179	}
180	
181	// rem128 returns (hi<<64 | lo) mod y for unsigned hi, lo and y > 0.
182	func rem128(hi, lo, y uint64) uint64 {
183		if hi >= y {
184			hi %= y
185		}
186		return bits.Rem64(hi, lo, y)
187	}
188	
189	// windowIndex locates the window starting at start in ws, which must be
190	// sorted by window start. The second result reports whether it exists;
191	// when it does not, the index is where it would be inserted to keep ws
192	// sorted, i.e. the first window whose start is not before start.
193	func windowIndex(ws []Window, start time.Time) (int, bool) {
194		sec, nsec := start.Unix(), int64(start.Nanosecond())
195		lo, hi := 0, len(ws)
196		for lo < hi {
197			mid := int(uint(lo+hi) >> 1)
198			s := ws[mid].Start
199			if ss, sn := s.Unix(), int64(s.Nanosecond()); ss < sec || (ss == sec && sn < nsec) {
200				lo = mid + 1
201			} else {
202				hi = mid
203			}
204		}
205		if lo < len(ws) {
206			if s := ws[lo].Start; s.Unix() == sec && int64(s.Nanosecond()) == nsec {
207				return lo, true
208			}
209		}
210		return lo, false
211	}
212	
213	// addTo folds one sample into w. Count saturates at math.MaxInt64 instead
214	// of overflowing; Sum, Min, and Max keep updating afterwards.
215	func addTo(w *Window, value float64) {
216		if w.Count < math.MaxInt64 {
217			w.Count++
218		}
219		w.Sum += value
220		if value < w.Min {
221			w.Min = value
222		}
223		if value > w.Max {
224			w.Max = value
225		}
226	}
227	
228	// Add files a sample into its window. A sample earlier than the most recent
229	// accepted sample is rejected with ErrOutOfOrder and leaves the roller
230	// unchanged; a sample at the same instant is accepted and counted again.
231	//
232	// Concurrent Adds are serialized: each takes effect in the order it
233	// acquires the roller, and the out-of-order check is measured against the
234	// samples accepted before it in that order.
235	func (r *Roller) Add(at time.Time, value float64) error {
236		r.mu.Lock()
237		defer r.mu.Unlock()
238		if r.hasAny && at.Before(r.latest) {
239			return ErrOutOfOrder
240		}
241		r.fileLocked(at, value)
242		r.latest = at
243		r.hasAny = true
244		return nil
245	}
246	
247	// AddBatch files a batch of samples as one atomic unit: either every
248	// sample takes effect or none does. The samples may arrive in any order
249	// and are not checked against each other; several samples at the same
250	// instant are each counted. Each sample is filed into its epoch-aligned
251	// window exactly as Add would file it.
252	//
253	// If any sample predates the most recent sample the roller has already
254	// accepted, the whole batch is rejected with ErrOutOfOrder and the roller
255	// is left unchanged. Otherwise the most-recent marker advances to the
256	// later of its previous value and the newest sample in the batch. A nil
257	// or empty batch is accepted, changes nothing, and does not advance the
258	// marker.
259	//
260	// The batch is atomic with respect to every other call on the roller:
261	// concurrent adds, batches, merges, range reads, and cursor creation
262	// observe the roller wholly before or wholly after the batch.
263	func (r *Roller) AddBatch(samples []Sample) error {
264		if len(samples) == 0 {
265			return nil
266		}
267		r.mu.Lock()
268		defer r.mu.Unlock()
269		// One pass to validate the batch against the accepted marker and find
270		// its newest instant; nothing is filed until every sample is known to
271		// be acceptable, so a rejection leaves the roller untouched.
272		latest := samples[0].At
273		for _, s := range samples {
274			if r.hasAny && s.At.Before(r.latest) {
275				return ErrOutOfOrder
276			}
277			if s.At.After(latest) {
278				latest = s.At
279			}
280		}
281		for _, s := range samples {
282			r.fileLocked(s.At, s.Value)
283		}
284		if r.hasAny && r.latest.After(latest) {
285			latest = r.latest
286		}
287		r.latest = latest
288		r.hasAny = true
289		return nil
290	}
291	
292	// fileLocked folds one sample into its window. The caller must hold mu
293	// and must already have cleared the out-of-order check.
294	func (r *Roller) fileLocked(at time.Time, value float64) {
295		start := r.startOf(at)
296		n := len(r.buckets)
297		switch {
298		case n == 0:
299			r.buckets = append(r.buckets, newBucket(start, value))
300		case !start.Before(r.buckets[n-1].Start):
301			// The common case: the sample lands in the newest window or
302			// just past it, so the sorted order is maintained for free.
303			if r.buckets[n-1].Start.Equal(start) {
304				addTo(&r.buckets[n-1], value)
305			} else {
306				r.buckets = append(r.buckets, newBucket(start, value))
307			}
308		default:
309			// The sample belongs to an older window, which can only happen
310			// after a merge brought in windows past latest. A window that
311			// already exists is updated in place; a new one goes into the
312			// backfill buffer, so inserting it never shifts the tail of
313			// buckets and the cost of a mass backfill does not grow with
314			// the number of windows already accepted.
315			if i, ok := windowIndex(r.buckets, start); ok {
316				addTo(&r.buckets[i], value)
317			} else if i, ok := windowIndex(r.back, start); ok {
318				addTo(&r.back[i], value)
319			} else {
320				r.back = append(r.back, Window{})
321				copy(r.back[i+1:], r.back[i:])
322				r.back[i] = newBucket(start, value)
323				r.maybeFlushBack()
324			}
325		}
326	}
327	
328	// newBucket returns a window holding a single sample.
329	func newBucket(start time.Time, value float64) Window {
330		return Window{Start: start, Count: 1, Sum: value, Min: value, Max: value}
331	}
332	
333	// maybeFlushBack folds the backfill buffer into buckets once it holds at
334	// least half as many windows, so the merge cost amortizes to constant
335	// time per backfilled window. The caller must hold mu.
336	func (r *Roller) maybeFlushBack() {
337		if len(r.back)*2 >= len(r.buckets) {
338			r.buckets = mergeWindows(r.buckets, r.back)
339			r.back = nil
340		}
341	}
342	
343	// mergeWindows returns the sorted union of two window slices, each sorted
344	// by window start, combining the statistics of windows that share a
345	// start: counts and sums add, minimums take the smaller, maximums take
346	// the larger. The result is always a fresh slice.
347	func mergeWindows(a, b []Window) []Window {
348		merged := make([]Window, 0, len(a)+len(b))
349		i, j := 0, 0
350		for i < len(a) && j < len(b) {
351			switch {
352			case a[i].Start.Before(b[j].Start):
353				merged = append(merged, a[i])
354				i++
355			case b[j].Start.Before(a[i].Start):
356				merged = append(merged, b[j])
357				j++
358			default:
359				w := a[i]
360				w.Count = satAdd(w.Count, b[j].Count)
361				w.Sum += b[j].Sum
362				if b[j].Min < w.Min {
363					w.Min = b[j].Min
364				}
365				if b[j].Max > w.Max {
366					w.Max = b[j].Max
367				}
368				merged = append(merged, w)
369				i++
370				j++
371			}
372		}
373		merged = append(merged, a[i:]...)
374		merged = append(merged, b[j:]...)
375		return merged
376	}
377	
378	// Window returns the bucket whose start matches start exactly. The second
379	// result is false when no bucket starts at that instant; no nearby bucket
380	// is substituted. The returned Window is a copy and stays valid no matter
381	// what is filed afterwards.
382	func (r *Roller) Window(start time.Time) (Window, bool) {
383		r.mu.RLock()
384		defer r.mu.RUnlock()
385		if i, ok := windowIndex(r.buckets, start); ok {
386			return r.buckets[i], true
387		}
388		if i, ok := windowIndex(r.back, start); ok {
389			return r.back[i], true
390		}
391		return Window{}, false
392	}
393	
394	// Windows returns all buckets in time order. An empty roller yields an
395	// empty slice. The result is a snapshot of one moment: samples filed after
396	// the call do not alter it.
397	func (r *Roller) Windows() []Window {
398		r.mu.RLock()
399		defer r.mu.RUnlock()
400		if len(r.back) != 0 {
401			return mergeWindows(r.buckets, r.back)
402		}
403		out := make([]Window, len(r.buckets))
404		copy(out, r.buckets)
405		return out
406	}
407	
408	// Range returns the buckets that overlap the half-open interval
409	// [from, to), in time order. The endpoints are attributed to windows by
410	// the same epoch-aligned, left-closed rule Add uses: the first bucket
411	// returned is the one containing from, and a bucket starting exactly at
412	// to is excluded. An interval whose end does not come after its start
413	// yields an empty slice, as does an interval no bucket overlaps. The
414	// result is a snapshot of one moment: samples filed after the call do
415	// not alter it.
416	func (r *Roller) Range(from, to time.Time) []Window {
417		r.mu.RLock()
418		defer r.mu.RUnlock()
419		out := []Window{}
420		if !from.Before(to) {
421			return out
422		}
423		lo := r.startOf(from)
424		i, _ := windowIndex(r.buckets, lo)
425		j, _ := windowIndex(r.back, lo)
426		for {
427			var w Window
428			switch {
429			case i < len(r.buckets) && (j >= len(r.back) || r.buckets[i].Start.Before(r.back[j].Start)):
430				w = r.buckets[i]
431				i++
432			case j < len(r.back):
433				w = r.back[j]
434				j++
435			default:
436				return out
437			}
438			if !w.Start.Before(to) {
439				return out
440			}
441			out = append(out, w)
442		}
443	}
444	
445	// Cursor reads a fixed range of windows in batches. The windows are
446	// snapshot when the cursor is created: samples filed, backfilled, or
447	// merged in afterwards do not alter what the cursor returns, so batched
448	// iteration over a large range never tears, skips, or repeats a window,
449	// and the end of the range is reached deterministically no matter what
450	// is written while the cursor advances.
451	//
452	// A Cursor is safe to advance from multiple goroutines at once; each
453	// batch is handed out exactly once.
454	type Cursor struct {
455		// mu guards pos. windows is fixed at creation and read without the
456		// lock.
457		mu      sync.Mutex
458		windows []Window
459		pos     int
460	}
461	
462	// Cursor returns a cursor over the buckets overlapping the half-open
463	// interval [from, to), selected by the same rule as Range.
464	func (r *Roller) Cursor(from, to time.Time) *Cursor {
465		return &Cursor{windows: r.Range(from, to)}
466	}
467	
468	// Next returns the next batch of up to n windows, in time order. Batches
469	// are consecutive and non-overlapping: together they cover exactly the
470	// windows in the cursor's range. Once the range is exhausted, Next
471	// returns an empty slice and the cursor does not move. A non-positive n
472	// yields an empty slice and does not advance the cursor.
473	func (c *Cursor) Next(n int) []Window {
474		c.mu.Lock()
475		defer c.mu.Unlock()
476		rest := len(c.windows) - c.pos
477		if n <= 0 || rest == 0 {
478			return []Window{}
479		}
480		if n > rest {
481			n = rest
482		}
483		out := make([]Window, n)
484		copy(out, c.windows[c.pos:c.pos+n])
485		c.pos += n
486		return out
487	}
488	
489	// Merge folds other's buckets into this roller: counts and sums add,
490	// minimums take the smaller, maximums take the larger, and buckets only one
491	// side has are carried over as-is. Merging does not affect out-of-order
492	// tracking. It panics with "rollup: nil roller" if other is nil, and
493	// returns ErrWindowMismatch, leaving this roller unchanged, if the window
494	// sizes differ.
495	//
496	// The merge is atomic with respect to every other call on either roller:
497	// concurrent readers see this roller wholly before or wholly after the
498	// merge, and a sample filed into other while the merge runs is either
499	// folded in completely or not at all. If the two rollers merge each other
500	// at the same time, the outcome matches some serial order of the two
501	// merges; neither is lost.
502	func (r *Roller) Merge(other *Roller) error {
503		if other == nil {
504			panic("rollup: nil roller")
505		}
506		if other.window != r.window {
507			return ErrWindowMismatch
508		}
509		if r == other {
510			r.mu.Lock()
511			defer r.mu.Unlock()
512			for _, buckets := range [][]Window{r.buckets, r.back} {
513				for i := range buckets {
514					w := &buckets[i]
515					w.Count = satAdd(w.Count, w.Count)
516					w.Sum += w.Sum
517				}
518			}
519			return nil
520		}
521		// Lock both rollers in ID order so simultaneous merges in
522		// opposite directions cannot deadlock.
523		first, second := r, other
524		if other.id < r.id {
525			first, second = other, r
526		}
527		first.mu.Lock()
528		second.mu.Lock()
529		defer second.mu.Unlock()
530		defer first.mu.Unlock()
531	
532		switch {
533		case len(other.buckets) == 0 && len(other.back) == 0:
534			return nil
535		case len(r.buckets) == 0 && len(r.back) == 0:
536			r.buckets = mergeWindows(other.buckets, other.back)
537			return nil
538		}
539		left, right := r.buckets, other.buckets
540		if len(r.back) != 0 {
541			left = mergeWindows(r.buckets, r.back)
542		}
543		if len(other.back) != 0 {
544			right = mergeWindows(other.buckets, other.back)
545		}
546		// Both sides are sorted by window start, so the merge is one linear
547		// pass and one backing array, no per-bucket copies or lookups.
548		r.buckets = mergeWindows(left, right)
549		r.back = nil
550		return nil
551	}
552	
553	// satAdd returns a + b saturated at math.MaxInt64 instead of overflowing.
554	func satAdd(a, b int64) int64 {
555		if b > math.MaxInt64-a {
556			return math.MaxInt64
557		}
558		return a + b
559	}
