1	// Command rollupctl reads timestamped samples from a file, files them into
2	// fixed windows aligned to the Unix epoch, and prints, one per line, each
3	// window's start, count, sum, minimum, and maximum.
4	//
5	// Usage:
6	//
7	//	rollupctl --file <path> --window <duration> windows
8	//
9	// The input file holds one sample per line: an integer number of
10	// nanoseconds since the epoch, whitespace, then a floating-point value.
11	// Blank and whitespace-only lines carry no sample. Samples must arrive in
12	// non-decreasing time order.
13	//
14	// Exit codes: 0 success, 2 bad command-line arguments, 3 the input file
15	// does not exist or is a directory, 4 the input file's contents are
16	// invalid.
17	package main
18	
19	import (
20		"bufio"
21		"errors"
22		"fmt"
23		"io"
24		"math"
25		"math/big"
26		"os"
27		"strconv"
28		"strings"
29		"time"
30	
31		"github.com/Hulalalalalalalalalalala/metric-rollup/rollup"
32	)
33	
34	// maxLineBytes is the longest accepted physical input line, excluding the
35	// line terminator.
36	const maxLineBytes = 1024
37	
38	func main() {
39		os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
40	}
41	
42	// run parses args, reads the input file, and writes the window listing.
43	// It returns the process exit code; every diagnostic is a single line on
44	// stderr prefixed with "rollupctl: ".
45	func run(args []string, stdout, stderr io.Writer) int {
46		file, window, ok := parseArgs(args, stderr)
47		if !ok {
48			return 2
49		}
50		d, err := time.ParseDuration(window)
51		if err != nil {
52			argError(stderr, "invalid --window %q: %v", window, err)
53			return 2
54		}
55		if d <= 0 {
56			argError(stderr, "--window must be positive, got %s", d)
57			return 2
58		}
59	
60		info, err := os.Stat(file)
61		if err != nil {
62			fmt.Fprintf(stderr, "rollupctl: %s\n", err)
63			return 3
64		}
65		if info.IsDir() {
66			fmt.Fprintf(stderr, "rollupctl: %s: is a directory\n", file)
67			return 3
68		}
69		f, err := os.Open(file)
70		if err != nil {
71			fmt.Fprintf(stderr, "rollupctl: %s\n", err)
72			return 3
73		}
74		roller, code := ingest(f, file, d, stderr)
75		f.Close()
76		if code != 0 {
77			return code
78		}
79	
80		out := bufio.NewWriter(stdout)
81		for _, w := range roller.Windows() {
82			fmt.Fprintf(out, "%s %d %s %s %s\n",
83				unixNanoText(w.Start), w.Count,
84				formatFloat(w.Sum), formatFloat(w.Min), formatFloat(w.Max))
85		}
86		if err := out.Flush(); err != nil {
87			fmt.Fprintf(stderr, "rollupctl: %s\n", err)
88			return 1
89		}
90		return 0
91	}
92	
93	// argError writes one command-line usage diagnostic.
94	func argError(stderr io.Writer, format string, a ...any) {
95		fmt.Fprintf(stderr, "rollupctl: "+format+"\n", a...)
96	}
97	
98	// parseArgs extracts the windows subcommand, the --file path, and the
99	// --window duration. Flags may stand on either side of the subcommand,
100	// Go-style: --name value, --name=value, with one or two leading dashes.
101	func parseArgs(args []string, stderr io.Writer) (file, window string, ok bool) {
102		fail := func(format string, a ...any) (string, string, bool) {
103			argError(stderr, format, a...)
104			return "", "", false
105		}
106		sub := ""
107		flagsEnded := false
108		for i := 0; i < len(args); i++ {
109			a := args[i]
110			if !flagsEnded && a == "--" {
111				flagsEnded = true
112				continue
113			}
114			if flagsEnded || !strings.HasPrefix(a, "-") || a == "-" {
115				if a != "windows" || sub != "" {
116					return fail("unexpected argument %q", a)
117				}
118				sub = a
119				continue
120			}
121			name := a[1:]
122			if strings.HasPrefix(name, "-") {
123				name = name[1:]
124			}
125			value := ""
126			inline := false
127			if k := strings.IndexByte(name, '='); k >= 0 {
128				value = name[k+1:]
129				name = name[:k]
130				inline = true
131			}
132			switch name {
133			case "file", "window":
134				if !inline {
135					i++
136					if i >= len(args) {
137						return fail("flag --%s needs a value", name)
138					}
139					value = args[i]
140				}
141				if value == "" {
142					return fail("flag --%s needs a value", name)
143				}
144				if name == "file" {
145					file = value
146				} else {
147					window = value
148				}
149			default:
150				return fail("unexpected argument %q", a)
151			}
152		}
153		if sub == "" {
154			return fail("expected the windows subcommand")
155		}
156		if file == "" {
157			return fail("--file is required")
158		}
159		if window == "" {
160			return fail("--window is required")
161		}
162		return file, window, true
163	}
164	
165	// ingest streams the samples from in into a fresh roller. On any content
166	// problem it returns code 4 after writing one diagnostic naming the file
167	// and line; no sample lines are printed by the caller in that case.
168	func ingest(in io.Reader, name string, d time.Duration, stderr io.Writer) (*rollup.Roller, int) {
169		contentError := func(line int, reason string) (*rollup.Roller, int) {
170			fmt.Fprintf(stderr, "rollupctl: %s:%d: %s\n", name, line, reason)
171			return nil, 4
172		}
173	
174		// The line buffer is capped at one byte over the limit, so a longer
175		// line fails immediately instead of growing with the file.
176		sc := bufio.NewScanner(in)
177		sc.Buffer(make([]byte, maxLineBytes+1), maxLineBytes+1)
178	
179		roller := rollup.New(d)
180		line := 0
181		samples := 0
182		for sc.Scan() {
183			line++
184			text := sc.Text()
185			if strings.TrimSpace(text) == "" {
186				continue
187			}
188			fields := strings.Fields(text)
189			if len(fields) != 2 {
190				return contentError(line, "expected a nanosecond timestamp and a value separated by whitespace")
191			}
192			ns, err := strconv.ParseInt(fields[0], 10, 64)
193			if err != nil {
194				return contentError(line, fmt.Sprintf("invalid timestamp %q", fields[0]))
195			}
196			value, err := strconv.ParseFloat(fields[1], 64)
197			if err != nil {
198				return contentError(line, fmt.Sprintf("invalid value %q", fields[1]))
199			}
200			if math.IsNaN(value) || math.IsInf(value, 0) {
201				return contentError(line, "value must be finite")
202			}
203			if err := roller.Add(time.Unix(0, ns).UTC(), value); err != nil {
204				return contentError(line, err.Error())
205			}
206			samples++
207		}
208		if err := sc.Err(); err != nil {
209			if errors.Is(err, bufio.ErrTooLong) {
210				// The over-long line is the one after every line already
211				// delivered, including an unterminated last line.
