324	func TestFormatFloatRoundTrip(t *testing.T) {
325		// Every distinct float64 in a dense sweep round-trips through the
326		// chosen formatting.
327		for bits := uint64(0); bits < 200000; bits++ {
328			v := math.Float64frombits(bits)
329			if math.IsNaN(v) || math.IsInf(v, 0) {
330				continue
331			}
332			s := formatFloat(v)
333			back, err := strconv.ParseFloat(s, 64)
334			if err != nil || back != v {
